<template><el-container style="height:100vh"><el-aside width="230px" style="background:#0f172a"><div style="color:white;font-weight:700;font-size:18px;padding:22px">Risk Intelligence</div><el-menu router background-color="#0f172a" text-color="#cbd5e1" active-text-color="#60a5fa" :default-active="$route.path"><el-menu-item v-for="m in menus" :key="m.path" :index="m.path" v-show="!m.perm||auth.has(m.perm)">{{m.label}}</el-menu-item></el-menu></el-aside><el-container><el-header style="background:white;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #eee"><b>企业经营风险智能分析与决策平台</b><div style="display:flex;align-items:center;gap:12px"><template v-if="ai.running"><el-tag type="warning" effect="dark" size="small">AI 分析进行中 {{(ai.elapsedMs/1000).toFixed(0)}}s</el-tag><el-button link type="primary" @click="goAi">查看</el-button><el-button link type="danger" @click="ai.cancel()">取消</el-button></template><template v-else-if="ai.status==='DONE'&&$route.path!=='/ai'"><el-tag type="success" effect="plain" size="small">AI 分析已完成</el-tag><el-button link type="primary" @click="goAi">查看结果</el-button></template><span>{{auth.user?.realName}}（{{auth.user?.roles?.join(',')}}）</span> <el-button link type="danger" @click="logout">退出</el-button></div></el-header><el-main style="padding:0;overflow:auto"><router-view/></el-main></el-container></el-container></template><script setup>import{useRouter}from'vue-router';import{useAuthStore}from'../stores/auth';import{useAiTaskStore}from'../stores/aiTask';const auth=useAuthStore(),ai=useAiTaskStore(),router=useRouter();const menus=[{path:'/dashboard',label:'经营看板',perm:'dashboard:read'},{path:'/companies',label:'企业管理',perm:'company:read'},{path:'/metrics',label:'经营指标',perm:'metric:read'},{path:'/import',label:'数据接入中心',perm:'import:write'},{path:'/rules',label:'风险规则',perm:'rule:read'},{path:'/risks',label:'风险事件',perm:'risk:read'},{path:'/complaints',label:'投诉数据',perm:'complaint:read'},{path:'/competitors',label:'竞品数据',perm:'competitor:read'},{path:'/knowledge',label:'知识库/RAG',perm:'knowledge:read'},{path:'/ai',label:'AI Agent分析',perm:'ai:analyze'},{path:'/audit',label:'审计与追溯',perm:'ai:audit'},{path:'/users',label:'用户权限',perm:'system:user:read'}];function logout(){auth.logout();router.push('/login')}function goAi(){if(router.currentRoute.value.path!=='/ai')router.push('/ai')}</script>
